script:
if (-not $IP -or -not $HOSTNAME) { throw 'IP and HOSTNAME are required' }
$hosts = Join-Path $env:SystemRoot 'System32\drivers\etc\hosts'
$entry = "$IP`t$HOSTNAME"
$present = Select-String -Path $hosts -SimpleMatch $entry -Quiet
if (-not $present) {
    Add-Content -Path $hosts -Value "`n# Pinecrest portal fast-route`n$entry"
}
